"""RoboTwin handover episode controller. Commands are issued one stage at a time from the CLI."""
import sys, json, argparse
from pathlib import Path
import numpy as np
sys.path.insert(0, '/opt/tools')
from rcb_client import Robot

RUNS=Path('/app/runs'); RUNS.mkdir(exist_ok=True)
r=Robot()
def save(res,label):
    idx=1+max([int(p.name[:3]) for p in RUNS.glob('[0-9][0-9][0-9]_*')] or [0])
    d=RUNS/f'{idx:03d}_{label}'; res.save(str(d))
    m=res.meta; p=np.asarray(m['proprio']['now'])
    print('RUN',d,'done',m.get('done'),'reason',m.get('reason'),'time_left',round(m.get('time_left_s',0),1),'physics',m.get('physics_steps_chunk'),'plan',m.get('plan'),'clipped',m.get('clipped'),flush=True)
    print('EE',np.round(p[14:28],4).tolist(),'TCP',np.round(p[56:70],4).tolist(),'GRIP',np.round(p[[6,13,36,43]],4).tolist(),flush=True)
    return res

def now(): return np.array(r.get_obs(cameras=('head_camera',),video='none').meta['proprio']['now'])
def ee(left=None,right=None,label='move'):
    p=now(); L=p[14:21].tolist()+[float(p[28])]; R=p[21:28].tolist()+[float(p[29])]
    if left is not None: L=list(left)
    if right is not None: R=list(right)
    return save(r.submit('ee_pose',np.array(L+R)[None,:],cameras=('head_camera','front_camera','left_camera','right_camera','observer_camera','world_camera1'),video='none',note=label),label)
def grip(l=None,rgt=None,label='grip',duration=1.0):
    p=now(); a=p[:14].copy(); b=a.copy()
    if l is not None: b[6]=l
    if rgt is not None: b[13]=rgt
    rows=np.linspace(a,b,max(2,int(duration/.05)+1))
    return save(r.submit('joint_position',rows,dt=.05,cameras=('head_camera','front_camera','left_camera','right_camera','observer_camera','world_camera1'),video='none',note=label),label)
def obs(label='observe',sec=0): return save(r.get_obs(cameras=('head_camera','front_camera','left_camera','right_camera','observer_camera','world_camera1'),seconds=sec,include_depth=True,video='none'),label)

if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('command',choices=['ee','grip','obs']);ap.add_argument('--left',nargs=8,type=float);ap.add_argument('--right',nargs=8,type=float);ap.add_argument('--l',type=float);ap.add_argument('--r',type=float);ap.add_argument('--label',default='stage');ap.add_argument('--sec',type=float,default=0);args=ap.parse_args()
    if args.command=='ee':ee(args.left,args.right,args.label)
    elif args.command=='grip':grip(args.l,args.r,args.label)
    else:obs(args.label,args.sec)
